// Turn the spreadsheet rows above into STAYS records.
const STAYS = (() => {
  const rows = [], text = STAYS_CSV.trim();
  let row = [], cell = "", q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') q = false; else cell += c; }
    else if (c === '"') q = true;
    else if (c === ",") { row.push(cell); cell = ""; }
    else if (c === "\n") { row.push(cell); rows.push(row); row = []; cell = ""; }
    else if (c !== "\r") cell += c;
  }
  row.push(cell); rows.push(row);
  const head = rows.shift();
  const key = op => { const o = op.toLowerCase(); return o.startsWith("capenature") ? "cn" : o.startsWith("sanparks") ? "sp" : o.startsWith("community") ? "cm" : o.startsWith("municipal") ? "mu" : "pv"; };
  const phones = s => s.split(" / ").map(p => p.trim()).filter(Boolean).map(p => {
    const m = p.match(/^([^\d+]*)([+\d][\d ]+)$/);
    const label = m ? m[1].trim() : "", num = m ? m[2].trim() : p, d = num.replace(/\D/g, "");
    return [label, num, num.startsWith("+") ? "+" + d : d.startsWith("0") ? "+27" + d.slice(1) : d];
  });
  return rows.map(r => {
    const v = Object.fromEntries(head.map((h, i) => [h, r[i] || ""]));
    return {
      id: v["ID"], name: v["Name"], type: v["Type"], operator: v["Operator"], k: key(v["Operator"]), region: v["Region"],
      loc: v["Location"], hike: v["Nearby hiking"], lat: +v["Latitude"], lng: +v["Longitude"], gps: v["Coordinate source"] === "Published GPS",
      web: v["Website"] || v["Official website"], webType: v["Website type"] || "", phones: phones(v["Phone"]), email: v["Email"], book: v["Booking channel"],
      status: v["Contact status"], src: v["Source / listing checked"], notes: v["Notes"],
    };
  });
})();
